class Bookmaker {}

class Bettor {
  + name : string
  + id : int
}

class Race {
  + raceId : int
  + raceName : string
}

class Runner {
  + runnerId : int
  + horseName : string
}

class Jockey {
  + name : string
  + licenseNumber : string
}

class Bet {
  + amount : double
  + odds : double
}

Bettor "1" -- "0..*" Bet
Race "1" *-- "1..*" Runner
Runner "1" -- "1" Jockey
Race "1" -- "1" Runner : winner
Bet "0..*" -- "1" Race
Bet "0..*" -- "1" Runner
Bookmaker "1" -- "0..*" Bet : accepts
Bookmaker "1" -- "0..*" Bettor : manages

@enduml

